import {freeCanvasArea} from './ux.mjs';
import {taxonCountLabel,GERMANY_SUBSPECIES_STATUS} from './engine.mjs';
// Full visible hierarchy; rendering is limited to the current viewport, never the data.
export const NODE_WIDTH=300,NODE_HEIGHT=180,LEVEL_GAP=100,ROW_GAP=24,PAGE_SIZE=Infinity;
export function layoutTree(index,rootId,expanded){
 const nodes=[],edges=[],positions=new Map();let cursor=24;
 function walk(id,depth,parent=null){
  const taxon=index.byid.get(id);if(!taxon||!taxon.count)return null;
  const node={id,taxon,depth,parent,x:24+depth*(NODE_WIDTH+LEVEL_GAP),y:0,children:[]};nodes.push(node);positions.set(id,node);
  const children=taxon.children.filter(id=>index.byid.get(id).count);node.childCount=children.length;
  if(expanded.has(id))for(const child of children){walk(child,depth+1,id);node.children.push(child);edges.push({from:id,to:child});}
  if(node.children.length)node.y=depth===0&&node.children.length>20?positions.get(node.children[0]).y+NODE_HEIGHT*1.5:(positions.get(node.children[0]).y+positions.get(node.children.at(-1)).y)/2;
  else{node.y=cursor;cursor+=NODE_HEIGHT+ROW_GAP;}
  return node;
 }
 const root=walk(rootId,0);let width=0,height=0;for(const n of nodes){width=Math.max(width,n.x+NODE_WIDTH+24);height=Math.max(height,n.y+NODE_HEIGHT+24);}
 return {nodes,edges,positions,root,width,height};
}
export function expandSubtree(index,rootId){const expanded=new Set();function visit(id){const n=index.byid.get(id);if(!n||!n.count)return;if(n.children.some(id=>index.byid.get(id)?.count)){expanded.add(id);n.children.forEach(visit);}}visit(rootId);return expanded;}
export function branchPath(a,b){const x1=a.x+NODE_WIDTH,y1=a.y+NODE_HEIGHT/2,x2=b.x,y2=b.y+NODE_HEIGHT/2,mid=(x1+x2)/2;return `M${x1},${y1}C${mid},${y1} ${mid},${y2} ${x2},${y2}`;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let textContext;const widthCache=new Map();
export function measureTextWidth(text,font){const key=font+'|'+text;if(widthCache.has(key))return widthCache.get(key);if(textContext===undefined){try{textContext=globalThis.document?.createElement?.('canvas').getContext('2d')||null;}catch{textContext=null;}}let width;if(textContext){textContext.font=font;width=textContext.measureText(text).width;}else{const size=Number(font.match(/(\d+)px/)?.[1]||14);width=[...String(text)].reduce((sum,c)=>sum+(/[ilI.,' ]/.test(c)?.3:/[MW@]/.test(c)?.9:.56)*size,0);}if(widthCache.size>25000)widthCache.clear();widthCache.set(key,width);return width;}
// The last line reserves room for its small language suffix, not a permanent left column.
export function wrapCardText(text,font,{width=NODE_WIDTH-32,suffix=0,maxLines=2,measure=measureTextWidth}={}){
 const words=String(text).trim().split(/\s+/),out=[];let current='';
 for(const word of words){if(current&&measure(current+' '+word,font)>width){out.push(current);current=word;}else current=(current+' '+word).trim();}if(current)out.push(current);
 if(out.length===1&&measure(out[0],font)>width-suffix){const split=out[0].lastIndexOf(' ');if(split>0)out.splice(0,1,out[0].slice(0,split),out[0].slice(split+1));}
 if(!out.length)out.push('');if(out.length>maxLines)out.splice(maxLines-1,out.length,out.slice(maxLines-1).join(' '));
 return out.map((line,i)=>{const available=width-(i===out.length-1?suffix:0);if(measure(line,font)<=available)return line;let chars=[...line];while(chars.length&&measure(chars.join('')+'…',font)>available)chars.pop();return chars.join('').trimEnd()+'…';});
}
export function vernacular(n,lang){return n[lang]||(n.rank==='genus'?'in den Quellen nicht hinterlegt':'noch nicht zugeordnet');}
export function inViewport(n,v){return !v||(n.x+NODE_WIDTH>=v.left&&n.x<=v.right&&n.y+NODE_HEIGHT>=v.top&&n.y<=v.bottom);}
export function graphContents(layout,{expanded,selectedId,ranks,label,num},viewport=null,coarse=false,scale=.1){
 const ancestors=new Set();let a=layout.positions.get(selectedId);while(a){ancestors.add(a.id);a=layout.positions.get(a.parent);}
 const visible=layout.nodes.filter(n=>inViewport(n,viewport));let plain='',highlight='';
 for(const e of layout.edges){const a=layout.positions.get(e.from),b=layout.positions.get(e.to);if(viewport&&(b.x<viewport.left||a.x+NODE_WIDTH>viewport.right||Math.max(a.y,b.y)+NODE_HEIGHT<viewport.top||Math.min(a.y,b.y)>viewport.bottom))continue;const d=branchPath(a,b);if(ancestors.has(a.id)&&ancestors.has(b.id))highlight+=d;else plain+=d;}
 const branches=`<g class="branches" aria-hidden="true"><path class="branch" d="${plain}"/><path class="branch on-path" d="${highlight}"/></g>`;
 if(coarse){const boxes=visible.map(n=>`M${n.x},${n.y}h${NODE_WIDTH}v${NODE_HEIGHT}h-${NODE_WIDTH}z`).join('');const occupied=[];const labels=visible.filter(n=>['class','clade','order','family'].includes(n.taxon.rank)).sort((a,b)=>a.depth-b.depth).filter(n=>{const x=n.x*scale,y=n.y*scale;if(occupied.some(p=>Math.abs(p.x-x)<285&&Math.abs(p.y-y)<64))return false;occupied.push({x,y});return true;}).slice(0,20).map(n=>`<g class="semantic-label" role="button" tabindex="-1" data-overview-node="${esc(n.id)}" aria-label="${esc(n.taxon.name)}: Ausschnitt öffnen" transform="translate(${n.x} ${n.y}) scale(${1/scale})"><rect width="280" height="60" rx="4"/><text x="6" y="14">${esc(n.taxon.name)} · ${num(n.taxon.count)}</text><text class="semantic-common" x="6" y="32">DE: ${esc(vernacular(n.taxon,'de').slice(0,36))}</text><text class="semantic-common" x="6" y="49">EN: ${esc(vernacular(n.taxon,'en').slice(0,36))}</text></g>`).join('');return `${branches}<path class="overview-boxes" d="${boxes}"/>${labels}`;}
 const cards=visible.map(n=>{const t=n.taxon,isOpen=expanded.has(n.id),de=vernacular(t,'de'),en=vernacular(t,'en'),desc=`${ranks[t.rank]}: ${t.name}. Deutsch: ${de}. English: ${en}. ${taxonCountLabel(t,num)}.${t.rank==='subspecies'?' Deutschland: '+GERMANY_SUBSPECIES_STATUS[t.germany_status||'not_evaluated']+'.':''}${t.de_descriptive||t.en_descriptive?' Namen mit Stern sind beschreibende Anzeigen aus dem Artnamen und Unterartepitheton.':''}`;const deFont=`${t.de?'550':'400'} 18px system-ui`,enFont='400 16px system-ui',scientificFont=`${['genus','species','subspecies'].includes(t.rank)?'italic ':''}16px Georgia`;const deLines=wrapCardText(de,deFont,{suffix:t.de_descriptive?34:26}),enLines=wrapCardText(en,enFont,{suffix:t.en_descriptive?34:26}),scientificLines=wrapCardText(t.name,scientificFont);const deY=36,scientificY=deY+(deLines.length-1)*22+22,enY=scientificY+(scientificLines.length-1)*20+22,totalY=enY+(enLines.length-1)*20+23,cardHeight=totalY+12,cardTop=(NODE_HEIGHT-cardHeight)/2;const block=(content,cls,y,step)=>`<text class="${cls}" x="16" y="${y}">${content.map((line,i)=>`<tspan x="16" dy="${i?step:0}">${esc(line)}</tspan>`).join('')}</text>`;const suffix=(content,font,language,y,step)=>`<text class="node-language" x="${16+measureTextWidth(content.at(-1),font)+8}" y="${y+(content.length-1)*step}">${language}</text>`;
 return `<g class="graph-node ${n.id===selectedId?'selected':''} ${ancestors.has(n.id)?'on-path':''}" data-node-id="${esc(n.id)}" transform="translate(${n.x},${n.y})"><g transform="translate(0 ${cardTop})"><g class="node-hit" role="button" tabindex="-1" data-node-toggle="${esc(n.id)}" ${n.childCount?`aria-expanded="${isOpen}"`:''} aria-label="${esc(desc)}"><title>${esc(desc)}</title><rect class="node-card" width="${NODE_WIDTH}" height="${cardHeight}" rx="12"/><text class="node-rank" x="16" y="16">${esc(ranks[t.rank])}</text>${block(deLines,`node-label ${t.de?'':'name-missing'}`,deY,22)}${suffix(deLines,deFont,t.de_descriptive?'DE*':'DE',deY,22)}${block(scientificLines,`node-scientific ${['genus','species','subspecies'].includes(t.rank)?'scientific':''}`,scientificY,20)}${block(enLines,`node-english ${t.en?'':'name-missing'}`,enY,20)}${suffix(enLines,enFont,t.en_descriptive?'EN*':'EN',enY,20)}<text class="node-total" x="16" y="${totalY}">${t.rank==='subspecies'?'':taxonCountLabel(t,num)}${t.rank==='subspecies'?'Deutschland: '+({confirmed:'belegt',open:'offen',source_uncertain:'Quelle unsicher',not_evaluated:'ungeprüft'}[t.germany_status]||'ungeprüft'):''}${n.childCount&&t.rank!=='species'&&!t.subspeciesCount?' · '+n.childCount+(n.childCount===1?' Zweig':' Zweige'):''}</text>${n.childCount?`<circle class="node-port" data-node-expand="${esc(n.id)}" cx="${NODE_WIDTH}" cy="${cardHeight/2}" r="13"/><text class="node-plus" data-node-expand="${esc(n.id)}" x="${NODE_WIDTH}" y="${cardHeight/2+5}" text-anchor="middle">${isOpen?'−':'+'}</text>`:''}</g><g class="node-isolate" role="button" tabindex="-1" data-node-focus="${esc(n.id)}" aria-label="${esc(label(t))} als Teilbaum öffnen"><rect x="256" y="0" width="44" height="28" rx="10"/><text x="278" y="21" text-anchor="middle">↗</text></g></g></g>`;}).join('');return branches+cards;
}
export function graphMarkup(layout,options){return `<svg id="branch-canvas" role="group" aria-label="Interaktiver Taxonomiebaum, ${layout.nodes.length} aufgeklappte Knoten" tabindex="0"><g id="branch-scene"></g></svg>`;}
// One uniform map scale includes the entire viewport, even beyond the tree bounds.
export function minimapGeometry(layout,camera,width,height,mapWidth=220,mapHeight=140,bounds=null){
 const viewport={left:-camera.x/camera.z,top:-camera.y/camera.z,right:(width-camera.x)/camera.z,bottom:(height-camera.y)/camera.z};
 const left=Math.min(bounds?.left??0,viewport.left),top=Math.min(bounds?.top??0,viewport.top),right=Math.max(bounds?.right??layout.width,viewport.right),bottom=Math.max(bounds?.bottom??layout.height,viewport.bottom);
 const scale=Math.min((mapWidth-12)/(right-left),(mapHeight-12)/(bottom-top));
 return {viewport,scale,x:(mapWidth-(right-left)*scale)/2-left*scale,y:(mapHeight-(bottom-top)*scale)/2-top*scale};
}
export function attachCamera(svg,layout,state,{anchorId,reset=false,options}={}){
 const scene=svg.querySelector('#branch-scene'),host=svg.parentElement,rect=()=>host.getBoundingClientRect();let w=rect().width||800,h=rect().height||620;
 let camera=state.camera;
 if(reset||!camera){const z=1;camera={x:24-layout.root.x*z,y:h/2-(layout.root.y+NODE_HEIGHT/2)*z,z};state.camera=camera;}
 else if(anchorId&&state.positions?.has(anchorId)&&layout.positions.has(anchorId)){const old=state.positions.get(anchorId),next=layout.positions.get(anchorId);camera.x+=(old.x-next.x)*camera.z;camera.y+=(old.y-next.y)*camera.z;}
 state.positions=layout.positions;
 const mini=host.querySelector('#mini-map'),mw=220,mh=140;let mapGeometry;
 if(mini){mini.setAttribute('viewBox',`0 0 ${mw} ${mh}`);const boxes=layout.nodes.map(n=>`M${n.x},${n.y}h${NODE_WIDTH}v${NODE_HEIGHT}h-${NODE_WIDTH}z`).join('');const n=layout.positions.get(options.selectedId);mini.innerHTML=`<g class="mini-scene"><path class="mini-nodes" d="${boxes}"/>${n?`<circle class="mini-selected" cx="${n.x+NODE_WIDTH/2}" cy="${n.y+NODE_HEIGHT/2}"/>`:''}</g><rect class="mini-viewport"/>`;mini.onclick=e=>{const r=mini.getBoundingClientRect(),screenScale=Math.min(r.width/mw,r.height/mh),px=(e.clientX-r.left-(r.width-mw*screenScale)/2)/screenScale,py=(e.clientY-r.top-(r.height-mh*screenScale)/2)/screenScale;const x=(px-mapGeometry.x)/mapGeometry.scale,y=(py-mapGeometry.y)/mapGeometry.scale;camera.x=w/2-x*camera.z;camera.y=h/2-y*camera.z;apply();};}


 let frame=0;const paint=()=>{frame=0;const pad=90/camera.z,viewport={left:-camera.x/camera.z-pad,right:(w-camera.x)/camera.z+pad,top:-camera.y/camera.z-pad,bottom:(h-camera.y)/camera.z+pad};const focus=document.activeElement?.getAttribute('data-node-toggle');scene.innerHTML=graphContents(layout,options,viewport,camera.z<.45,camera.z);if(focus)scene.querySelector(`[data-node-toggle="${CSS.escape(focus)}"]`)?.focus({preventScroll:true});};
 const apply=()=>{options.onCameraChange?.();if(!frame)frame=requestAnimationFrame(paint);scene.setAttribute('transform',`translate(${camera.x} ${camera.y}) scale(${camera.z})`);const output=document.querySelector('#zoom-level');if(output)output.textContent=(camera.z<.01?(camera.z*100).toFixed(3):Math.round(camera.z*100))+' %';const box=mini?.querySelector('.mini-viewport');if(box){const vx=-camera.x/camera.z,vy=-camera.y/camera.z;mapGeometry=minimapGeometry(layout,camera,w,h,mw,mh,options.minimapLocal?{left:vx-w/camera.z,top:vy-h/camera.z,right:vx+2*w/camera.z,bottom:vy+2*h/camera.z}:null);const {viewport:v,scale:m,x,y}=mapGeometry;mini.querySelector('.mini-scene').setAttribute('transform',`translate(${x} ${y}) scale(${m})`);mini.querySelector('.mini-selected')?.setAttribute('r',4/m);box.setAttribute('x',x+v.left*m);box.setAttribute('y',y+v.top*m);box.setAttribute('width',(v.right-v.left)*m);box.setAttribute('height',(v.bottom-v.top)*m);}const guide=host.querySelector('.graph-map-guide');if(guide){guide.hidden=camera.z>=.45&&layout.root.childCount<=20;guide.textContent=camera.z<.45?'Übersicht · Knoten anklicken, um hineinzuzoomen. Die Liste zeigt alle Namen.':`${layout.root.childCount} Zweige · Fläche ziehen für weitere Zweige oder Liste wählen.`;}};
 const zoom=(factor,cx=w/2,cy=h/2)=>{const z=Math.max(.00001,Math.min(2,camera.z*factor)),ratio=z/camera.z;camera.x=cx-(cx-camera.x)*ratio;camera.y=cy-(cy-camera.y)*ratio;camera.z=z;apply();};
 const area=()=>{const details=host.closest('.branch-panel')?.querySelector('.detail');return freeCanvasArea(rect(),details&&getComputedStyle(details).position==='absolute'?details.getBoundingClientRect():null);};
 const center=id=>{const n=layout.positions.get(id)||layout.root,a=area();camera.x=(a.left+a.right)/2-(n.x+NODE_WIDTH/2)*camera.z;camera.y=(a.top+a.bottom)/2-(n.y+NODE_HEIGHT/2)*camera.z;apply();};
 const ensureVisible=id=>{const n=layout.positions.get(id)||layout.root,a=area(),left=camera.x+n.x*camera.z,top=camera.y+n.y*camera.z,right=left+NODE_WIDTH*camera.z,bottom=top+NODE_HEIGHT*camera.z;if(right-left>a.right-a.left||bottom-top>a.bottom-a.top){center(id);return;}if(left<a.left)camera.x+=a.left-left;else if(right>a.right)camera.x-=right-a.right;if(top<a.top)camera.y+=a.top-top;else if(bottom>a.bottom)camera.y-=bottom-a.bottom;apply();};
 const fit=()=>{const a=area();camera.z=Math.max(.00001,Math.min(1.2,(a.right-a.left)/layout.width,(a.bottom-a.top)/layout.height));camera.x=(a.left+a.right-layout.width*camera.z)/2;camera.y=(a.top+a.bottom-layout.height*camera.z)/2;apply();};
 const pan=direction=>{if(direction==='left')camera.x+=w*.65;if(direction==='right')camera.x-=w*.65;if(direction==='up')camera.y+=h*.65;if(direction==='down')camera.y-=h*.65;apply();};
 const pointers=new Map();let gesture=null,moved=false;
 svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(!e.target.closest('[role=button]'))svg.setPointerCapture(e.pointerId);moved=false;if(pointers.size===1)gesture={x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y};else{const [a,b]=[...pointers.values()];gesture={distance:Math.hypot(b.x-a.x,b.y-a.y),midX:(a.x+b.x)/2-rect().left,midY:(a.y+b.y)/2-rect().top,z:camera.z,x:camera.x,y:camera.y};}});
 svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1&&gesture&&gesture.distance===undefined){const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.hypot(dx,dy)>5){moved=true;svg.setPointerCapture(e.pointerId);}if(moved){camera.x=gesture.cx+dx;camera.y=gesture.cy+dy;apply();}}else if(pointers.size===2&&gesture?.distance){moved=true;const [a,b]=[...pointers.values()],distance=Math.hypot(b.x-a.x,b.y-a.y),z=Math.max(.00001,Math.min(2,gesture.z*distance/gesture.distance)),ratio=z/gesture.z,mx=(a.x+b.x)/2-rect().left,my=(a.y+b.y)/2-rect().top;camera.x=mx-(gesture.midX-gesture.x)*ratio;camera.y=my-(gesture.midY-gesture.y)*ratio;camera.z=z;apply();}});
 const release=e=>{pointers.delete(e.pointerId);if(pointers.size===1){const a=[...pointers.values()][0];gesture={x:a.x,y:a.y,cx:camera.x,cy:camera.y};}else if(!pointers.size)gesture=null;};
 svg.addEventListener('pointerup',release);svg.addEventListener('pointercancel',release);
 svg.addEventListener('click',e=>{if(moved){e.stopImmediatePropagation();e.preventDefault();moved=false;}else if(camera.z<.45){const x=(e.clientX-rect().left-camera.x)/camera.z,y=(e.clientY-rect().top-camera.y)/camera.z;const overviewId=e.target.closest('[data-overview-node]')?.dataset.overviewNode;const n=layout.positions.get(overviewId)||layout.nodes.find(n=>x>=n.x&&x<=n.x+NODE_WIDTH&&y>=n.y&&y<=n.y+NODE_HEIGHT);if(n){camera.z=1;center(n.id);e.stopImmediatePropagation();}}},true);
 svg.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)zoom(Math.exp(-e.deltaY*.006),e.clientX-rect().left,e.clientY-rect().top);else{camera.x-=e.deltaX;camera.y-=e.deltaY;apply();}},{passive:false});
 svg.addEventListener('keydown',e=>{if(e.target!==svg)return;const delta=65;if(e.key==='+'||e.key==='=')zoom(1.2);else if(e.key==='-')zoom(1/1.2);else if(e.key==='0')fit();else if(e.key==='ArrowLeft')camera.x+=delta;else if(e.key==='ArrowRight')camera.x-=delta;else if(e.key==='ArrowUp')camera.y+=delta;else if(e.key==='ArrowDown')camera.y-=delta;else return;e.preventDefault();apply();});
 const observer=new ResizeObserver(()=>{const r=rect();w=r.width;h=r.height;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);apply();});observer.observe(host);svg.setAttribute('viewBox',`0 0 ${w} ${h}`);apply();cancelAnimationFrame(frame);paint();
 return {zoom,fit,center,ensureVisible,paint,pan,destroy:()=>{observer.disconnect();cancelAnimationFrame(frame);}};
}
